package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var l, r int64
	fmt.Fscan(reader, &l, &r)

	n := 9
	ten := make([]int64, n+1)
	ten[0] = 1
	for i := 1; i <= n; i++ {
		ten[i] = 10 * ten[i-1]
	}

	var answer int64 = 0

	luckyNumbers := make([]int64, 0)

	for length := 1; length <= n; length++ {
		for cur := 0; cur < (1 << length); cur++ {
			var value int64 = 0
			for j := 0; j < length; j++ {
				if ((1 << j) & cur) == (1 << j) {
					value += ten[j] * 7
				} else {
					value += ten[j] * 4
				}
			}
			luckyNumbers = append(luckyNumbers, value)
		}
	}

	luckyNumbers = append(luckyNumbers, 4444444444)

	lastNumber := l

	for _, luckyNumber := range luckyNumbers {
		if luckyNumber > r {
			answer += (r - lastNumber + 1) * luckyNumber
			break
		}
		if luckyNumber >= l {
			answer += (luckyNumber - lastNumber + 1) * luckyNumber
			lastNumber = luckyNumber + 1
		}
	}

	fmt.Fprintln(writer, answer)
}
